import math
import numpy as np


def sharpe_by_period(pnl, dates, cutoff):
    pnl = np.asarray(pnl, dtype=float)
    after = np.array([d > cutoff for d in dates])
    def sr(x):
        return float(x.mean() / x.std(ddof=1) * math.sqrt(252))
    return sr(pnl[~after]), sr(pnl[after])

